mapper.select:
SELECT id, product_id, seckill_price, stock_count, available_count, start_time, end_time, status, creator_id, seckill_name, per_limit, images, description, is_deleted, create_time, update_time FROM t_seckill_goods WHERE is_deleted = 0
AND status = #{status}
AND product_id IN ( SELECT id FROM t_product WHERE is_deleted = 0
AND name LIKE CONCAT('%', #{keyword}, '%')
AND category_id = #{categoryId}
)
ORDER BY start_time DESC
